package csu.mengya.db;
import java.nio.file.*;import java.sql.*;import java.util.*;
public final class AppDatabase { private static final String URL="jdbc:sqlite:"+path(); private AppDatabase(){ } private static String path(){String p=System.getenv("LOCALAPPDATA");if(p==null||p.isBlank())p=System.getProperty("user.home");Path d=Paths.get(p,"pmato","data");try{Files.createDirectories(d);}catch(Exception e){throw new IllegalStateException(e);}return d.resolve("pmato.db").toString();} public static void init(){try(Connection c=DriverManager.getConnection(URL);Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS todo(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,priority TEXT NOT NULL,tomatoes INTEGER NOT NULL,done INTEGER NOT NULL DEFAULT 0)");s.executeUpdate("CREATE TABLE IF NOT EXISTS schedule_event(id INTEGER PRIMARY KEY AUTOINCREMENT,event_date TEXT NOT NULL,event_time TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL)");}catch(SQLException e){throw new IllegalStateException("数据库初始化失败",e);}} public static List<TodoRow> todos(){List<TodoRow> r=new ArrayList<>();try(Connection c=DriverManager.getConnection(URL);PreparedStatement p=c.prepareStatement("SELECT id,title,priority,tomatoes,done FROM todo ORDER BY done,id");ResultSet s=p.executeQuery()){while(s.next())r.add(new TodoRow(s.getLong(1),s.getString(2),s.getString(3),s.getInt(4),s.getBoolean(5)));}catch(SQLException e){throw new IllegalStateException(e);}return r;} public static long addTodo(String t,String p,int n){try(Connection c=DriverManager.getConnection(URL);PreparedStatement x=c.prepareStatement("INSERT INTO todo(title,priority,tomatoes) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){x.setString(1,t);x.setString(2,p);x.setInt(3,n);x.executeUpdate();try(ResultSet k=x.getGeneratedKeys()){k.next();return k.getLong(1);}}catch(SQLException e){throw new IllegalStateException(e);}} public static void updateTodo(long id,String t,String p,int n,boolean done){try(Connection c=DriverManager.getConnection(URL);PreparedStatement x=c.prepareStatement("UPDATE todo SET title=?,priority=?,tomatoes=?,done=? WHERE id=?")){x.setString(1,t);x.setString(2,p);x.setInt(3,n);x.setBoolean(4,done);x.setLong(5,id);x.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}} public static void deleteTodo(long id){exec("DELETE FROM todo WHERE id=?",id);} public static List<EventRow> events(){List<EventRow> r=new ArrayList<>();try(Connection c=DriverManager.getConnection(URL);PreparedStatement p=c.prepareStatement("SELECT id,event_date,event_time,name,type FROM schedule_event ORDER BY event_date,event_time");ResultSet s=p.executeQuery()){while(s.next())r.add(new EventRow(s.getLong(1),s.getString(2),s.getString(3),s.getString(4),s.getString(5)));}catch(SQLException e){throw new IllegalStateException(e);}return r;} public static long addEvent(String d,String t,String n,String y){try(Connection c=DriverManager.getConnection(URL);PreparedStatement x=c.prepareStatement("INSERT INTO schedule_event(event_date,event_time,name,type) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){x.setString(1,d);x.setString(2,t);x.setString(3,n);x.setString(4,y);x.executeUpdate();try(ResultSet k=x.getGeneratedKeys()){k.next();return k.getLong(1);}}catch(SQLException e){throw new IllegalStateException(e);}} public static void deleteEvent(long id){exec("DELETE FROM schedule_event WHERE id=?",id);} private static void exec(String q,long id){try(Connection c=DriverManager.getConnection(URL);PreparedStatement x=c.prepareStatement(q)){x.setLong(1,id);x.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}} public record TodoRow(long id,String title,String priority,int tomatoes,boolean done){} public record EventRow(long id,String date,String time,String name,String type){} }